CREATE TABLE public.internet_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, display_name text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', fornecedor_id uuid, collection_mode text NOT NULL DEFAULT 'manual' CHECK (collection_mode IN ('manual','api','portal')), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.internet_providers TO authenticated; GRANT ALL ON public.internet_providers TO service_role;
ALTER TABLE public.internet_providers ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_providers_read ON public.internet_providers FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_provider_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES public.internet_providers(id), holder_name text NOT NULL, holder_document text, account_label text NOT NULL, external_account_id text, credential_ref text, enabled boolean NOT NULL DEFAULT false, access_state text NOT NULL DEFAULT 'not_configured' CHECK (access_state IN ('not_configured','ready','intervention_required','disabled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,external_account_id));
GRANT SELECT ON public.internet_provider_accounts TO authenticated; GRANT ALL ON public.internet_provider_accounts TO service_role;
ALTER TABLE public.internet_provider_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_accounts_read ON public.internet_provider_accounts FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_collection_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL CHECK(scope IN ('all','provider','account')), provider_id uuid REFERENCES public.internet_providers(id), account_id uuid REFERENCES public.internet_provider_accounts(id), request_key uuid NOT NULL UNIQUE, requested_by uuid NOT NULL, trigger_type text NOT NULL DEFAULT 'manual' CHECK(trigger_type IN ('manual','scheduled')), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','partial','failed','not_configured')), expected_accounts integer NOT NULL DEFAULT 0, summary jsonb NOT NULL DEFAULT '{}', started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((scope='all' AND provider_id IS NULL AND account_id IS NULL) OR (scope='provider' AND provider_id IS NOT NULL AND account_id IS NULL) OR (scope='account' AND account_id IS NOT NULL AND provider_id IS NULL)));
GRANT SELECT ON public.internet_collection_runs TO authenticated; GRANT ALL ON public.internet_collection_runs TO service_role;
ALTER TABLE public.internet_collection_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_runs_read ON public.internet_collection_runs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_collection_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.internet_collection_runs(id), account_id uuid NOT NULL REFERENCES public.internet_provider_accounts(id), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','logging_in','collecting_contracts','collecting_invoices','downloading_documents','reconciling','completed','error','intervention_required')), attempt integer NOT NULL DEFAULT 0, phase_sequence bigint NOT NULL DEFAULT 0, lease_until timestamptz, heartbeat_at timestamptz, phase_changed_at timestamptz NOT NULL DEFAULT now(), error_code text, counts jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,account_id));
GRANT SELECT ON public.internet_collection_jobs TO authenticated; GRANT ALL ON public.internet_collection_jobs TO service_role;
ALTER TABLE public.internet_collection_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_jobs_read ON public.internet_collection_jobs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.internet_provider_accounts(id), external_contract_id text NOT NULL, access_id text, installation_address text, billing_cycle text, due_day integer CHECK(due_day BETWEEN 1 AND 31), portal_contract_status text, last_verified_run_id uuid REFERENCES public.internet_collection_runs(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,external_contract_id));
GRANT SELECT ON public.internet_contracts TO authenticated; GRANT ALL ON public.internet_contracts TO service_role;
ALTER TABLE public.internet_contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_contracts_read ON public.internet_contracts FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_contract_buildings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.internet_contracts(id), building_id uuid NOT NULL REFERENCES public.buildings(id), evidence_type text NOT NULL, state text NOT NULL DEFAULT 'suggested' CHECK(state IN ('suggested','confirmed','rejected')), verified_at timestamptz, verified_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contract_id,building_id), CHECK(state <> 'confirmed' OR (verified_at IS NOT NULL AND verified_by IS NOT NULL)));
GRANT SELECT ON public.internet_contract_buildings TO authenticated; GRANT ALL ON public.internet_contract_buildings TO service_role;
ALTER TABLE public.internet_contract_buildings ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_links_read ON public.internet_contract_buildings FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.internet_contracts(id), official_invoice_id text NOT NULL, invoice_number text, competence text, amount numeric(14,2) NOT NULL CHECK(amount >= 0), due_date date, portal_status text NOT NULL DEFAULT 'not_verified' CHECK(portal_status IN ('paid_portal','overdue_open','upcoming','cancelled_replaced','not_verified','intervention_required')), bank_status text NOT NULL DEFAULT 'not_verified' CHECK(bank_status IN ('not_verified','review','verified_by_official_id')), last_verified_run_id uuid REFERENCES public.internet_collection_runs(id), portal_observed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contract_id,official_invoice_id));
GRANT SELECT ON public.internet_invoices TO authenticated; GRANT ALL ON public.internet_invoices TO service_role;
ALTER TABLE public.internet_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_invoices_read ON public.internet_invoices FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_invoice_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.internet_collection_runs(id), job_id uuid NOT NULL REFERENCES public.internet_collection_jobs(id), invoice_id uuid NOT NULL REFERENCES public.internet_invoices(id), portal_status text NOT NULL, amount numeric(14,2) NOT NULL, due_date date, observed_at timestamptz NOT NULL DEFAULT now(), evidence_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,invoice_id,evidence_hash));
GRANT SELECT ON public.internet_invoice_observations TO authenticated; GRANT ALL ON public.internet_invoice_observations TO service_role;
ALTER TABLE public.internet_invoice_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_observations_read ON public.internet_invoice_observations FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_invoice_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.internet_invoices(id), portal_payment_id text, paid_at timestamptz, bank_provider text, bank_movement_id text, bank_status text NOT NULL DEFAULT 'not_verified' CHECK(bank_status IN ('not_verified','review','verified_by_official_id')), verified_by uuid, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invoice_id,portal_payment_id), CHECK(bank_status <> 'verified_by_official_id' OR (bank_movement_id IS NOT NULL AND verified_at IS NOT NULL)));
GRANT SELECT ON public.internet_invoice_payments TO authenticated; GRANT ALL ON public.internet_invoice_payments TO service_role;
ALTER TABLE public.internet_invoice_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_payments_read ON public.internet_invoice_payments FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.internet_invoices(id), run_id uuid NOT NULL REFERENCES public.internet_collection_runs(id), document_type text NOT NULL CHECK(document_type IN ('invoice','receipt')), storage_path text NOT NULL UNIQUE, sha256 text NOT NULL, official_document_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invoice_id,document_type,sha256));
GRANT SELECT ON public.internet_documents TO authenticated; GRANT ALL ON public.internet_documents TO service_role;
ALTER TABLE public.internet_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_documents_read ON public.internet_documents FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_exceptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.internet_collection_runs(id), job_id uuid REFERENCES public.internet_collection_jobs(id), account_id uuid REFERENCES public.internet_provider_accounts(id), contract_id uuid REFERENCES public.internet_contracts(id), invoice_id uuid REFERENCES public.internet_invoices(id), code text NOT NULL, state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved')), safe_message text NOT NULL, resolved_by uuid, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.internet_exceptions TO authenticated; GRANT ALL ON public.internet_exceptions TO service_role;
ALTER TABLE public.internet_exceptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_exceptions_read ON public.internet_exceptions FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE TABLE public.internet_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.internet_collection_runs(id), account_id uuid REFERENCES public.internet_provider_accounts(id), actor_id uuid, actor_type text NOT NULL CHECK(actor_type IN ('admin','worker','system')), event_type text NOT NULL, entity_type text NOT NULL, entity_id uuid, safe_details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.internet_audit_events TO authenticated; GRANT ALL ON public.internet_audit_events TO service_role;
ALTER TABLE public.internet_audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY internet_audit_read ON public.internet_audit_events FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin'));
CREATE INDEX internet_jobs_account_state_idx ON public.internet_collection_jobs(account_id,state); CREATE INDEX internet_invoices_run_idx ON public.internet_invoices(last_verified_run_id); CREATE INDEX internet_observations_run_idx ON public.internet_invoice_observations(run_id); CREATE INDEX internet_exceptions_run_idx ON public.internet_exceptions(run_id,state); CREATE INDEX internet_contracts_account_idx ON public.internet_contracts(account_id); CREATE INDEX internet_runs_created_idx ON public.internet_collection_runs(created_at DESC);
CREATE OR REPLACE FUNCTION public.internet_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['internet_providers','internet_provider_accounts','internet_collection_runs','internet_collection_jobs','internet_contracts','internet_contract_buildings','internet_invoices','internet_invoice_observations','internet_invoice_payments','internet_documents','internet_exceptions','internet_audit_events'] LOOP EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.internet_touch_updated_at()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.internet_dispatch_collection(p_scope text,p_provider_id uuid,p_account_id uuid,p_request_key uuid,p_actor_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_run uuid; v_count integer; BEGIN IF auth.role() <> 'service_role' OR p_actor_id IS NULL THEN RAISE EXCEPTION 'Not authorized'; END IF; IF p_scope NOT IN ('all','provider','account') OR p_request_key IS NULL OR (p_scope='provider' AND p_provider_id IS NULL) OR (p_scope='account' AND p_account_id IS NULL) OR (p_scope='all' AND (p_provider_id IS NOT NULL OR p_account_id IS NOT NULL)) OR (p_scope='provider' AND p_account_id IS NOT NULL) OR (p_scope='account' AND p_provider_id IS NOT NULL) THEN RAISE EXCEPTION 'Invalid scope'; END IF; PERFORM pg_advisory_xact_lock(hashtext('internet_collection_dispatch')); SELECT id INTO v_run FROM public.internet_collection_runs WHERE request_key=p_request_key; IF v_run IS NOT NULL THEN RETURN v_run; END IF; SELECT r.id INTO v_run FROM public.internet_collection_runs r JOIN public.internet_collection_jobs j ON j.run_id=r.id JOIN public.internet_provider_accounts a ON a.id=j.account_id WHERE r.state IN ('queued','running') AND j.state NOT IN ('completed','error','intervention_required') AND a.enabled AND (p_scope='all' OR (p_scope='provider' AND a.provider_id=p_provider_id) OR (p_scope='account' AND a.id=p_account_id)) LIMIT 1; IF v_run IS NOT NULL THEN RETURN v_run; END IF; INSERT INTO public.internet_collection_runs(scope,provider_id,account_id,request_key,requested_by) VALUES(p_scope,p_provider_id,p_account_id,p_request_key,p_actor_id) RETURNING id INTO v_run; INSERT INTO public.internet_collection_jobs(run_id,account_id) SELECT v_run,a.id FROM public.internet_provider_accounts a JOIN public.internet_providers p ON p.id=a.provider_id WHERE a.enabled AND a.access_state='ready' AND a.credential_ref IS NOT NULL AND p.enabled AND (p_scope='all' OR (p_scope='provider' AND p.id=p_provider_id) OR (p_scope='account' AND a.id=p_account_id)); GET DIAGNOSTICS v_count=ROW_COUNT; UPDATE public.internet_collection_runs SET expected_accounts=v_count,state=CASE WHEN v_count=0 THEN 'not_configured' ELSE 'queued' END,finished_at=CASE WHEN v_count=0 THEN now() ELSE NULL END WHERE id=v_run; INSERT INTO public.internet_audit_events(run_id,actor_id,actor_type,event_type,entity_type,entity_id,safe_details) VALUES(v_run,p_actor_id,'admin','collection_requested','run',v_run,jsonb_build_object('scope',p_scope,'expected_accounts',v_count)); RETURN v_run; END $$;
REVOKE ALL ON FUNCTION public.internet_dispatch_collection(text,uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.internet_dispatch_collection(text,uuid,uuid,uuid,uuid) TO service_role;